import{LitElement,html}from"lit";import{createStore,TanStackStoreSelector}from"@tanstack/lit-store";
const defaults=()=>({open:false,count:0,value:"initial",items:[]});
const declarations={open:{type:Boolean,reflect:true,useDefault:true},count:{type:Number,reflect:true,useDefault:true},value:{type:String,reflect:true,useDefault:true},items:{attribute:false}};
function make(mode){class Probe extends LitElement{
 static properties=declarations;
 stateStore=createStore(defaults());
 derived=createStore(()=>JSON.stringify(this.stateStore.get()));
 selector=new TanStackStoreSelector(this,()=>this.derived);
 names=[];
 allowUpdate=true;
 constructor(){super();Object.assign(this,defaults());}
 commit(name,value){this[name]=value;}
 shouldUpdate(){return this.allowUpdate;}
 willUpdate(){if(mode==="update")this.stateStore.setState(()=>({open:this.open,count:this.count,value:this.value,items:this.items}));}
 updated(ch){this.names=[...ch.keys()];}
 render(){return html`<span>${this.derived.get()}</span>`;}
}
if(mode==="direct"){for(const name of Object.keys(declarations))Object.defineProperty(Probe.prototype,name,{configurable:true,enumerable:true,get(){return this.stateStore.get()[name];},set(value){this.stateStore.setState(old=>Object.is(old[name],value)?old:{...old,[name]:value});}});}
return Probe;}
const results=[];
for(const mode of ["direct","update"]){const tag="state-comparison-"+mode;customElements.define(tag,make(mode));const el=document.createElement(tag);document.body.append(el);await el.updateComplete;
const row={mode,checks:[],differences:[]};const check=(name,ok)=>row.checks.push({name,ok});
check("default attributes absent",!el.hasAttribute("count")&&!el.hasAttribute("value"));
el.count=0;await el.updateComplete;check("same default explicitly reflects",el.getAttribute("count")==="0");
el.count=7;row.differences.push({name:"store agrees immediately after property write",ok:el.stateStore.get().count===7});await el.updateComplete;
check("number render and reflect",JSON.parse(el.shadowRoot.querySelector("span").textContent).count===7&&el.getAttribute("count")==="7");
el.removeAttribute("count");await el.updateComplete;check("attribute removal restores default",el.count===0&&el.stateStore.get().count===0&&!el.hasAttribute("count"));
el.setAttribute("count","12");await el.updateComplete;check("number attribute conversion",el.count===12&&el.stateStore.get().count===12);
el.setAttribute("open","");await el.updateComplete;check("boolean conversion",el.open===true&&el.stateStore.get().open===true);
const items=["a","b"];el.items=items;await el.updateComplete;check("array identity preserved without reflection",el.stateStore.get().items===items&&!el.hasAttribute("items"));
el.commit("value","internal");row.differences.push({name:"store agrees immediately after internal property-gate write",ok:el.stateStore.get().value==="internal"});await el.updateComplete;
check("internal property-gate reflects and names change",el.getAttribute("value")==="internal"&&el.names.includes("value"));
el.remove();document.body.append(el);await el.updateComplete;el.count=14;await el.updateComplete;check("reconnect public write",el.stateStore.get().count===14&&el.getAttribute("count")==="14");
el.allowUpdate=false;el.count=15;await el.updateComplete;row.differences.push({name:"canonical state independent of rendering gate",ok:el.stateStore.get().count===15});
el.allowUpdate=true;el.requestUpdate();await el.updateComplete;
el.stateStore.setState(s=>({...s,value:"raw-store"}));await el.updateComplete;
row.differences.push({name:"unbridged raw store write preserves public getter",ok:el.value==="raw-store"});
row.differences.push({name:"unbridged raw store write reflects attribute",ok:el.getAttribute("value")==="raw-store"});
results.push(row);el.remove();}
console.log(JSON.stringify({runtime:"Bun and happy-dom with installed Lit/TanStack packages; no browser certification",results},null,2));
